@st.cache_data(ttl=86400)  # 24 horas — composición de índices cambia poco
def _cargar_wikipedia_index(url: str, sufijo: str = "") -> dict:
    """Extrae {nombre: ticker} de la tabla más relevante de una página Wikipedia."""
    try:
        import requests as _req, io as _io_wiki
        _ua = {"User-Agent": "Mozilla/5.0 (compatible; PivotAnalyzer/1.0)"}
        _resp = _req.get(url, headers=_ua, timeout=12)
        _resp.raise_for_status()
        tablas = pd.read_html(_io_wiki.StringIO(_resp.text))
        for t in tablas:
            cols = [c for c in t.columns if isinstance(c, str)]
            # Detectar columna de ticker y de nombre (EN + ES)
            t_col = next((c for c in cols if any(k in c.lower()
                          for k in ["ticker", "symbol", "code", "abbreviation",
                                    "símbolo", "simbolo"])), None)
            n_col = next((c for c in cols if any(k in c.lower()
                          for k in ["company", "security", "name", "stock",
                                    "empresa", "nombre", "compañía", "compania",
                                    "sociedad"])), None)
            if t_col and n_col:
                df = t[[n_col, t_col]].dropna()
                result = {}
                for _, row in df.iterrows():
                    nombre = str(row[n_col]).strip()
                    ticker = str(row[t_col]).strip()
                    if ":" in ticker:           # formato EXCHANGE:TICKER
                        ticker = ticker.split(":")[-1]
                    if sufijo and "." not in ticker:
                        ticker = ticker + sufijo
                    result[nombre] = ticker
                if len(result) > 5:
                    return dict(sorted(result.items()))
    except Exception:
        pass
    return {}


def obtener_tickers_mercado(mercado: str) -> dict:
    """Retorna {nombre: ticker_yfinance} para el mercado seleccionado."""
    if mercado == "🇪🇸 IBEX 35":
        return IBEX_35
    if mercado == "🌍 Eurostoxx 50":
        return EUROSTOXX_50
    if mercado == "🇺🇸 S&P 500":
        datos = _cargar_wikipedia_index(
            "https://en.wikipedia.org/wiki/List_of_S%26P_500_companies")
        return datos or _FALLBACK_SP500
    if mercado == "🇺🇸 Nasdaq 100":
        datos = _cargar_wikipedia_index(
            "https://en.wikipedia.org/wiki/Nasdaq-100")
        return datos or _FALLBACK_NDX
    if mercado == "🇺🇸 Dow Jones 30":
        datos = _cargar_wikipedia_index(
            "https://en.wikipedia.org/wiki/Dow_Jones_Industrial_Average")
        return datos or _FALLBACK_DOW
    if mercado == "🇩🇪 DAX 40":
        datos = _cargar_wikipedia_index(
            "https://en.wikipedia.org/wiki/DAX", sufijo=".DE")
        return datos or _FALLBACK_DAX
    if mercado == "🇫🇷 CAC 40":
        datos = _cargar_wikipedia_index(
            "https://en.wikipedia.org/wiki/CAC_40", sufijo=".PA")
        return datos or _FALLBACK_CAC
    if mercado == "🇬🇧 FTSE 100":
        datos = _cargar_wikipedia_index(
            "https://en.wikipedia.org/wiki/FTSE_100_Index", sufijo=".L")
        return datos or _FALLBACK_FTSE
    if mercado == "🇪🇸 IBEX Medium Cap":
        return IBEX_MEDIUM_CAP
    if mercado == "🇪🇸 IBEX Small Cap":
        return IBEX_SMALL_CAP
    return {}


# =============================================================================
# CONEXIÓN NEON (PostgreSQL) — connection pool via psycopg2
# @st.cache_resource mantiene el pool vivo entre reruns (no se destruye en cada interacción)
# =============================================================================

@st.cache_resource
def _get_db_pool():
    """Pool de conexiones persistente. Se crea una sola vez por sesión de servidor."""
    from psycopg2 import pool as pg_pool
    return pg_pool.ThreadedConnectionPool(
        minconn=1,
        maxconn=8,
        dsn=st.secrets["DATABASE_URL"],
        connect_timeout=10,
    )

def get_db_connection():
    """Obtiene una conexión del pool. Devolver siempre con release_db_connection()."""
    pool = _get_db_pool()
    for _attempt in range(3):
        try:
            conn = pool.getconn()
            if conn.closed:
                pool.putconn(conn, close=True)
                continue
            # Ping activo: detecta conexiones muertas por idle timeout del servidor
            conn.cursor().execute("SELECT 1")
            conn.rollback()   # cierra la txn del ping y limpia cualquier estado (incl. abortado) heredado
            return conn
        except Exception:
            # Conexión muerta — descartarla del pool y reintentar
            try:
                pool.putconn(conn, close=True)
            except Exception:
                pass
    # Fallback: conexión directa si el pool falla repetidamente
    return psycopg2.connect(st.secrets["DATABASE_URL"])

def release_db_connection(conn):
    """Devuelve la conexión al pool (no la cierra). Rollback previo: nunca devolver
    una conexión con transacción abierta o abortada (envenenaría al siguiente uso)."""
    try:
        try:
            conn.rollback()
        except Exception:
            pass
        _get_db_pool().putconn(conn)
    except Exception:
        try:
            conn.close()
        except Exception:
            pass

def db_select(tabla: str, filtros: dict = None):
    conn = get_db_connection()
    try:
        with conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cur:
            query = f"SELECT * FROM {tabla}"
            params = []
            if filtros:
                conds = [f"{col} = %s" for col in filtros]
                query += " WHERE " + " AND ".join(conds)
                params = list(filtros.values())
            cur.execute(query, params)
            return [dict(row) for row in cur.fetchall()]
    except Exception:
        conn.rollback()
        raise
    finally:
        release_db_connection(conn)

def db_insert(tabla: str, datos: dict):
    conn = get_db_connection()
    try:
        with conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cur:
            cols = ", ".join(datos.keys())
            vals = ", ".join(["%s"] * len(datos))
            query = f"INSERT INTO {tabla} ({cols}) VALUES ({vals}) RETURNING *"
            cur.execute(query, list(datos.values()))
            conn.commit()
            return [dict(cur.fetchone())]
    except Exception:
        conn.rollback()
        raise
    finally:
        release_db_connection(conn)

def db_update(tabla: str, datos: dict, filtro_col: str, filtro_val):
    conn = get_db_connection()
    try:
        with conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cur:
            sets = ", ".join([f"{k} = %s" for k in datos])
            query = f"UPDATE {tabla} SET {sets} WHERE {filtro_col} = %s RETURNING *"
            cur.execute(query, list(datos.values()) + [filtro_val])
            conn.commit()
            return [dict(row) for row in cur.fetchall()]
    except Exception:
        conn.rollback()
        raise
    finally:
        release_db_connection(conn)

def db_delete(tabla: str, filtro_col: str, filtro_val):
    conn = get_db_connection()
    try:
        with conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cur:
            query = f"DELETE FROM {tabla} WHERE {filtro_col} = %s RETURNING *"
            cur.execute(query, [filtro_val])
            conn.commit()
            return [dict(row) for row in cur.fetchall()]
    except Exception:
        conn.rollback()
        raise
    finally:
        release_db_connection(conn)


