_TIPOS_VALIDOS = ('dividendos', 'crecimiento', 'indexada', 'swing', 'multiactivo')


def inicializar_tabla_carteras():
    """Crea las tablas carteras y cartera_posiciones si no existen (idempotente)."""
    try:
        conn = get_db_connection()
        try:
            with conn.cursor() as cur:
                cur.execute("""
                    CREATE TABLE IF NOT EXISTS carteras (
                        id          SERIAL PRIMARY KEY,
                        usuario_id  INTEGER NOT NULL,
                        tipo        VARCHAR(20) NOT NULL
                                    CHECK (tipo IN ('dividendos','crecimiento','indexada','swing','multiactivo')),
                        nombre      VARCHAR(100) NOT NULL,
                        descripcion TEXT DEFAULT '',
                        created_at  TIMESTAMP DEFAULT NOW()
                    )
                """)
                cur.execute("""
                    CREATE TABLE IF NOT EXISTS cartera_posiciones (
                        id             SERIAL PRIMARY KEY,
                        cartera_id     INTEGER NOT NULL REFERENCES carteras(id) ON DELETE CASCADE,
                        ticker         VARCHAR(20) NOT NULL,
                        nombre_valor   VARCHAR(200) DEFAULT '',
                        num_acciones   NUMERIC(15,4) NOT NULL,
                        precio_compra  NUMERIC(15,4) NOT NULL,
                        moneda         VARCHAR(10) DEFAULT 'EUR',
                        notas          TEXT DEFAULT '',
                        created_at     TIMESTAMP DEFAULT NOW(),
                        updated_at     TIMESTAMP DEFAULT NOW(),
                        UNIQUE (cartera_id, ticker)
                    )
                """)
            conn.commit()
        finally:
            release_db_connection(conn)
    except Exception:
        pass

    # ── Migración: ampliar CHECK constraint para incluir nuevos tipos ──────────
    # Transacción separada para que un fallo no revierta la creación de tablas.
    try:
        conn2 = get_db_connection()
        try:
            with conn2.cursor() as cur2:
                # Buscar constraints de CHECK sobre la columna tipo que no incluyan multiactivo
                cur2.execute("""
                    SELECT conname
                    FROM pg_constraint c
                    JOIN pg_class t ON c.conrelid = t.oid
                    WHERE t.relname = 'carteras'
                      AND c.contype = 'c'
                      AND pg_get_constraintdef(c.oid) LIKE %s
                      AND pg_get_constraintdef(c.oid) NOT LIKE %s
                """, ('%tipo%', '%multiactivo%'))
                filas = cur2.fetchall()
                for (conname,) in filas:
                    cur2.execute(
                        f"ALTER TABLE carteras DROP CONSTRAINT {conname}"
                    )
                    cur2.execute("""
                        ALTER TABLE carteras ADD CONSTRAINT carteras_tipo_check
                        CHECK (tipo IN ('dividendos','crecimiento','indexada','swing','multiactivo'))
                    """)
            conn2.commit()
        finally:
            release_db_connection(conn2)
    except Exception:
        pass


def _drop_tipo_constraint() -> None:
    """Elimina el CHECK constraint de tipo en carteras y lo recrea incluyendo todos los tipos válidos.
    Se llama automáticamente cuando crear_cartera detecta una violación de constraint."""
    try:
        conn = get_db_connection()
        try:
            with conn.cursor() as cur:
                # Buscar todos los CHECK constraints de la tabla carteras
                cur.execute("""
                    SELECT conname
                    FROM pg_constraint c
                    JOIN pg_class t ON c.conrelid = t.oid
                    WHERE t.relname = 'carteras' AND c.contype = 'c'
                """)
                for (cname,) in cur.fetchall():
                    try:
                        cur.execute(
                            'ALTER TABLE carteras DROP CONSTRAINT IF EXISTS "' + cname + '"'
                        )
                    except Exception:
                        conn.rollback()
                # Recrear con todos los tipos válidos
                cur.execute("""
                    ALTER TABLE carteras ADD CONSTRAINT carteras_tipo_check
                    CHECK (tipo IN ('dividendos','crecimiento','indexada','swing','multiactivo'))
                """)
            conn.commit()
        except Exception:
            try: conn.rollback()
            except Exception: pass
        finally:
            release_db_connection(conn)
    except Exception:
        pass


def crear_cartera(usuario_id: int, tipo: str, nombre: str, descripcion: str = "") -> dict | None:
    """Crea una cartera. Devuelve el registro creado o None si ya hay 3 del mismo tipo."""
    _INSERT_SQL = """INSERT INTO carteras (usuario_id, tipo, nombre, descripcion)
                     VALUES (%s,%s,%s,%s)
                     RETURNING id, usuario_id, tipo, nombre, descripcion, created_at"""

    def _intentar(conn) -> dict | None:
        with conn.cursor() as cur:
            cur.execute(
                "SELECT COUNT(*) FROM carteras WHERE usuario_id=%s AND tipo=%s",
                [usuario_id, tipo]
            )
            if cur.fetchone()[0] >= 3:
                return None
            cur.execute(_INSERT_SQL, [usuario_id, tipo, nombre, descripcion])
            row = cur.fetchone()
        conn.commit()
        return {"id": row[0], "usuario_id": row[1], "tipo": row[2],
                "nombre": row[3], "descripcion": row[4], "created_at": row[5]}

    # Primer intento
    try:
        conn = get_db_connection()
        try:
            return _intentar(conn)
        except psycopg2.errors.CheckViolation:
            # El constraint no incluye el nuevo tipo — corregir y reintentar
            try: conn.rollback()
            except Exception: pass
        except Exception:
            return None
        finally:
            release_db_connection(conn)
    except Exception:
        return None

    # Corregir constraint y segundo intento
    _drop_tipo_constraint()
    try:
        conn = get_db_connection()
        try:
            return _intentar(conn)
        finally:
            release_db_connection(conn)
    except Exception:
        return None


