def verificar_password(password: str, hash_stored: str) -> bool:
    try:
        return bcrypt.checkpw(password.encode('utf-8'), hash_stored.encode('utf-8'))
    except Exception:
        return False


def hash_password(password: str) -> str:
    return bcrypt.hashpw(password.encode('utf-8'), bcrypt.gensalt(12)).decode('utf-8')


def login_usuario(username: str, password: str):
    """Retorna dict del usuario si login correcto, None si falla."""
    try:
        datos = db_select("usuarios", {"username": username, "activo": True})
        if not datos:
            return None
        user = datos[0]
        if verificar_password(password, user["password_hash"]):
            db_update("usuarios", {"ultimo_acceso": datetime.now().isoformat()}, "id", user["id"])
            return user
        return None
    except Exception as e:
        st.error(f"Error de autenticación: {e}")
        return None


# ── Sesiones persistentes (sobreviven F5) ─────────────────────────────────
_SESS_FILE = _Path(__file__).parent / ".pivot_sessions.json"

def _sess_load():
    try:
        if _SESS_FILE.exists():
            return _json_mod.loads(_SESS_FILE.read_text(encoding="utf-8"))
    except Exception:
        pass
    return {}

def _sess_save(d: dict):
    try:
        _SESS_FILE.write_text(_json_mod.dumps(d), encoding="utf-8")
    except Exception:
        pass

def _sess_create(user: dict) -> str:
    token = _hashlib_mod.sha256(
        f"{user['username']}{_uuid_mod.uuid4()}".encode()
    ).hexdigest()[:40]
    d = _sess_load()
    d[token] = user["username"]
    if len(d) > 200:
        d = dict(list(d.items())[-200:])
    _sess_save(d)
    return token

def _sess_get_user(token: str):
    if not token:
        return None
    d = _sess_load()
    username = d.get(token)
    if not username:
        return None
    try:
        datos = db_select("usuarios", {"username": username, "activo": True})
        return datos[0] if datos else None
    except Exception:
        return None

def _sess_delete(token: str):
    d = _sess_load()
    d.pop(token, None)
    _sess_save(d)


