# Tenores confirmados con datos en el ECB YC API.
# SR_6M, SR_2Y, SR_5Y, SR_7Y, SR_10Y, SR_30Y devuelven serie vacía en el API actual.
_YC_TENORES_DISPONIBLES = {
    "3M": "SR_3M",
    "1Y": "SR_1Y",
    "3Y": "SR_3Y",
    "15Y": "SR_15Y",
    "20Y": "SR_20Y",
}


@st.cache_data(ttl=86400)
def _obtener_tipo_ecb_yc(tenor: str) -> "float | None":
    """Tipo spot curva AAA Euro Area para un tenor.
    Tenores con datos directos: 3M, 1Y, 3Y, 15Y, 20Y.
    Para el resto usa interpolación lineal sobre los puntos disponibles.
    """
    # Tenores en años para interpolación
    _tenor_years = {
        "3M": 0.25, "6M": 0.5,
        "1Y": 1.0, "2Y": 2.0, "3Y": 3.0,
        "5Y": 5.0, "7Y": 7.0, "10Y": 10.0,
        "15Y": 15.0, "20Y": 20.0, "30Y": 30.0,
    }
    target_yr = _tenor_years.get(tenor)
    if target_yr is None:
        return None
    # Direct lookup first
    sr = _YC_TENORES_DISPONIBLES.get(tenor)
    if sr is not None:
        return obtener_dato_ecb(f"B.U2.EUR.4F.G_N_A.SV_C_YM.{sr}", flow_ref="YC")
    # Interpolate from available points
    pts = []
    for t, s in _YC_TENORES_DISPONIBLES.items():
        v = obtener_dato_ecb(f"B.U2.EUR.4F.G_N_A.SV_C_YM.{s}", flow_ref="YC")
        if v is not None:
            pts.append((_tenor_years[t], v))
    if len(pts) < 2:
        return None
    pts.sort()
    xs = [p[0] for p in pts]
    ys = [p[1] for p in pts]
    # Linear interpolation / flat extrapolation
    if target_yr <= xs[0]:
        return ys[0]
    if target_yr >= xs[-1]:
        return ys[-1]
    for i in range(len(xs) - 1):
        if xs[i] <= target_yr <= xs[i + 1]:
            frac = (target_yr - xs[i]) / (xs[i + 1] - xs[i])
            return ys[i] + frac * (ys[i + 1] - ys[i])
    return None


@st.cache_data(ttl=86400)
def _obtener_historico_yc(tenor: str, n_obs: int = 60) -> "pd.Series | None":
    """Histórico mensual de la curva AAA Euro Area para un tenor dado."""
    # Tenores con datos disponibles en ECB YC API: 3M, 1Y, 3Y, 15Y, 20Y
    _map = {
        "3M": "SR_3M", "1Y": "SR_1Y",
        "3Y": "SR_3Y", "15Y": "SR_15Y", "20Y": "SR_20Y",
    }
    sr = _map.get(tenor)
    if not sr:
        return None
    return obtener_historico_ecb("YC", f"B.U2.EUR.4F.G_N_A.SV_C_YM.{sr}", n_obs)


@st.cache_data(ttl=1800)
def _obtener_tipo_pais_ecb(pais: str, tenor: str = "10Y") -> "float | None":
    """Tipo gobierno 10Y por país vía ECB IRS (Maastricht criterion rates).
    pais: 'ES','DE','FR','IT','PT','NL','BE'
    """
    # ECB ILM dataset — Maastricht long-term government bond yields (convergence criteria)
    # Serie: M.{CC}.EUR.RT.LB.A.A207.HSTA
    series_key = f"M.{pais}.EUR.RT.LB.A.A207.HSTA"
    val = obtener_dato_ecb(series_key, flow_ref="ILM")
    if val is not None:
        return val
    # Fallback 1: ILM alternative key
    series_key2 = f"M.{pais}.EUR.RT.LB.A.A207.HP"
    val2 = obtener_dato_ecb(series_key2, flow_ref="ILM")
    if val2 is not None:
        return val2
    # Fallback 2: ECB dataset
    series_key3 = f"M.{pais}.EUR.RT.LB.A.A207.HSTA"
    return obtener_dato_ecb(series_key3, flow_ref="ECB")


def _rf_metric(label: str, valor, suffix: str = "%", delta=None, help_txt: str = ""):
    """Tarjeta métrica unificada para renta fija."""
    if valor is None:
        st.metric(label, "N/D", help=help_txt)
    else:
        d_str = None
        if delta is not None:
            d_str = f"{delta:+.2f} pp"
        st.metric(label, f"{valor:.2f}{suffix}", delta=d_str, help=help_txt)


def _rf_card(titulo: str, tir: "float|None", plazo: str,
             color: str = "#1e3a5f", bg: str = "#f0f4ff",
             descripcion: str = ""):
    """Tarjeta visual para un instrumento de renta fija."""
    tir_txt = f"{tir:.2f}%" if tir is not None else "N/D"
    tir_color = "#16a34a" if (tir or 0) >= 0 else "#dc2626"
    st.markdown(
        f'<div style="background:{bg};border-left:4px solid {color};'
        f'border-radius:8px;padding:12px 16px;margin-bottom:8px">'
        f'<div style="font-size:11px;color:{color};font-weight:700;'
        f'text-transform:uppercase;letter-spacing:.5px">{plazo}</div>'
        f'<div style="font-size:22px;font-weight:800;color:{tir_color}">{tir_txt}</div>'
        f'<div style="font-size:12px;color:#64748b;margin-top:2px">{titulo}</div>'
        f'{"<div style=font-size:11px;color:#94a3b8;margin-top:3px>" + descripcion + "</div>" if descripcion else ""}'
        f'</div>',
        unsafe_allow_html=True
    )



@st.cache_data(ttl=86400)
def obtener_euribor_3m() -> "float | None":
    """Euribor 3M diario — scrape de euribor-rates.eu (misma fuente que 12M)."""
    try:
        from bs4 import BeautifulSoup
        headers = {"User-Agent": "Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36"}
        r = requests.get("https://www.euribor-rates.eu/current-euribor-rates.asp",
                         headers=headers, timeout=15)
        if r.status_code != 200:
            return None
        soup = BeautifulSoup(r.text, "html.parser")
        table = soup.find("table")
        if not table:
            return None
        for row in table.find_all("tr"):
            cells = [c.get_text(strip=True) for c in row.find_all(["th", "td"])]
            if cells and "3" in cells[0] and "month" in cells[0].lower():
                val_str = cells[1].replace("%", "").replace(",", ".").strip()
                return float(val_str)
        return None
    except Exception:
        return None


