                f'<div style="font-size:12px;color:#475569;margin-top:3px">'
                f'Tama&#241;o: <b>{h["gap_pct"]:.2f}%</b> &nbsp;&middot;&nbsp; '
                f'Distancia: <b style="color:{_dcolor}">{_dstr}</b></div>'
