    # ── Pre-compute shared values for HTML report ──────────────────────────────
    # ── Alertas Fundamentales (cards individuales) ───────────────────────────
    _alertas_section_h = ""
    if info:
        _fa_ind = _alertas_fundamentales(info, div_ttm)
        if _fa_ind:
            _BG_H  = {"rojo": "#fef2f2", "amarillo": "#fefce8", "verde": "#f0fdf4"}
