# Mapa mercado → ticker de índice de referencia para beta
INDICE_BETA_MAP = {
    "🇪🇸 IBEX 35":         "^IBEX",
    "🇪🇸 IBEX Medium Cap": "^IBEX",
    "🇪🇸 IBEX Small Cap":  "^IBEX",
    "🌍 Eurostoxx 50":  "^STOXX50E",
    "🇺🇸 S&P 500":      "^GSPC",
    "🇺🇸 Nasdaq 100":   "^NDX",
    "🇺🇸 Dow Jones 30": "^DJI",
    "🇩🇪 DAX 40":       "^GDAXI",
    "🇫🇷 CAC 40":       "^FCHI",
    "🇬🇧 FTSE 100":     "^FTSE",
    "📊 ETFs UCITS":    "^STOXX50E",
}

def indice_ref_para_ticker(ticker: str, mercado_sel: str = "") -> tuple:
    """Devuelve (ticker_indice, nombre_indice) según mercado o sufijo del ticker."""
    if mercado_sel and mercado_sel in INDICE_BETA_MAP:
        t = INDICE_BETA_MAP[mercado_sel]
        return t, mercado_sel.split(" ", 1)[-1].strip()
    # Inferir por sufijo cuando se escribe manualmente
    sufijo = ticker.upper().split(".")[-1] if "." in ticker else ""
    mapa_sufijo = {
        "MC": ("^IBEX",     "IBEX 35"),
        "DE": ("^GDAXI",    "DAX 40"),
        "PA": ("^FCHI",     "CAC 40"),
        "L":  ("^FTSE",     "FTSE 100"),
        "AS": ("^STOXX50E", "Eurostoxx 50"),
        "MI": ("^FTSEMIB",  "FTSE MIB"),
        "LS": ("^PSI20",    "PSI 20"),
        "BR": ("^BFX",      "BEL 20"),
    }
    if sufijo in mapa_sufijo:
        return mapa_sufijo[sufijo]
    return "^GSPC", "S&P 500"  # fallback universal

@st.cache_data(ttl=3600)
def calcular_beta_vs_indice(ticker: str, indice_ticker: str, periodo: str = "2y") -> float | None:
    """Calcula beta del ticker contra el índice dado usando retornos diarios."""
    try:
        import pandas as pd
        t_hist  = yf.Ticker(ticker).history(period=periodo, auto_adjust=True)["Close"]
        i_hist  = yf.Ticker(indice_ticker).history(period=periodo, auto_adjust=True)["Close"]
        if t_hist.empty or i_hist.empty:
            return None
        # Alinear por fecha
        df = pd.DataFrame({"stock": t_hist, "indice": i_hist}).dropna()
        if len(df) < 60:
            return None
        ret_s = df["stock"].pct_change().dropna()
        ret_i = df["indice"].pct_change().dropna()
        df2 = pd.concat([ret_s, ret_i], axis=1).dropna()
        cov   = df2.cov().iloc[0, 1]
        var_i = df2.iloc[:, 1].var()
        if var_i == 0:
            return None
        return round(cov / var_i, 3)
    except Exception:
        return None

def calcular_div_ttm(ticker: str) -> float:
    """Dividendo anual real (TTM): suma de pagos reales en los últimos 12 meses.
    Evita el error de Yahoo Finance que suma 4 pagos aunque la empresa pague 3 veces al año."""
    try:
        import pandas as pd
        t = yf.Ticker(ticker)
        divs = t.dividends
        if divs is None or len(divs) == 0:
            return 0.0
        cutoff = pd.Timestamp.now(tz="UTC") - pd.DateOffset(months=12)
        ttm = float(divs[divs.index >= cutoff].sum())
        return ttm if ttm > 0 else 0.0
    except Exception:
        return 0.0


def obtener_comparativa_etf(categoria: str, ticker_actual: str) -> list[dict]:
    """Devuelve lista ordenada por TER de todos los ETFs de la categoría,
    enriquecidos con AUM y rentabilidad 1 año desde yfinance."""
    import yfinance as yf
    etfs_cat = ETFS_UCITS.get(categoria, {})
    resultado = []
    for nombre, tkr in etfs_cat.items():
        meta = ETFS_META.get(tkr, {})
        ter  = meta.get("ter")
        dist = meta.get("dist", "—")
        indice = meta.get("indice", "—")
        # Nombre corto: parte tras "— "
        nombre_corto = nombre.split("— ")[-1] if "— " in nombre else nombre
        aum = None
        rent_1a = None
        try:
            info = yf.Ticker(tkr).info
            aum  = info.get("totalAssets")
            hist = yf.Ticker(tkr).history(period="1y")
            if len(hist) >= 2:
                rent_1a = (hist["Close"].iloc[-1] / hist["Close"].iloc[0] - 1) * 100
        except Exception:
            pass
        resultado.append({
            "ticker":       tkr,
            "nombre_corto": nombre_corto,
            "ter":          ter,
            "dist":         dist,
            "indice":       indice,
            "aum":          aum,
            "rent_1a":      rent_1a,
            "actual":       tkr == ticker_actual,
        })
    resultado.sort(key=lambda x: (x["ter"] is None, x["ter"] or 99))
    return resultado




